echo "Creating bd tasks for ${#TESTS[@]} failing e2e tests..."

for test_line in "${TESTS[@]}"; do
    # Extract test file and line number (e.g., "tests/01-guest.spec.ts:162")
    test_file_line=$(echo "$test_line" | sed -E 's/ › .*//')
    test_file=$(echo "$test_file_line" | cut -d: -f1)
    test_line_num=$(echo "$test_file_line" | cut -d: -f2)

    # Extract test name (everything after the first " › ")
    test_name=$(echo "$test_line" | sed -E 's/^[^›]* › //')

    # Create a short title from the test name (last part)
    title=$(echo "$test_name" | awk -F' › ' '{print $NF}')

    # Create description with full test path and instructions
    description="Fix failing e2e test: $test_name

Test location: $test_file:$test_line_num

To run this test:
  bin/test-e2e-single '$test_file:$test_line_num'

Fix the application code (not the test code) to make this test pass."

    # Create bd task
    devenv shell -- bd create "Fix e2e test: $title" \
        -t bug \
        -p 2 \
        -d "$description" \
        --json > /dev/null 2>&1 || echo "Failed to create task for: $test_line"
done

echo "Done! Created tasks for ${#TESTS[@]} failing tests."
